import{_ as t,o as d,c as o,a0 as a}from"./chunks/framework.CKZJaUMN.js";const l=JSON.parse('{"title":"Wire API","description":"","frontmatter":{},"headers":[],"relativePath":"reference/wire-api.md","filePath":"reference/wire-api.md"}'),i={name:"reference/wire-api.md"};function r(c,e,n,s,p,h){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="wire-api" tabindex="-1">Wire API <a class="header-anchor" href="#wire-api" aria-label="Permalink to &quot;Wire API&quot;">​</a></h1><p>The entity-plane HTTP surface — served by the node host (<code>hypha-http</code>), aggregated by the hub (<code>hypha-hub</code>). One canonical spelling per route: <code>hypha-node-api</code>&#39;s <code>HttpEntityApi</code> and the hub speak the same paths. (The P3-era alias spellings — <code>/api/entities/{id}/export</code>, <code>/api/entities/import</code>, <code>/api/index</code>, <code>/api/outbox</code> — are gone.)</p><h2 id="node-surface" tabindex="-1">Node surface <a class="header-anchor" href="#node-surface" aria-label="Permalink to &quot;Node surface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Route</th><th>Verb</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/api/health</code></td><td>GET</td><td>liveness probe (pre-auth)</td></tr><tr><td><code>/api/pair</code></td><td>POST</td><td>redeem a pairing code → bearer token</td></tr><tr><td><code>/api/auth/login</code> <code>/api/auth/logout</code></td><td>POST</td><td>auth-cookie exchange</td></tr><tr><td><code>/api/user</code></td><td>GET</td><td>OS user info for pickers</td></tr><tr><td><code>/api/node</code></td><td>GET/PATCH</td><td>node descriptor / rename</td></tr><tr><td><code>/api/fs?path=</code></td><td>GET</td><td>direct subdirectories of an absolute path</td></tr><tr><td><code>/api/events</code></td><td>GET</td><td>SSE event feed</td></tr><tr><td><code>/api/entities</code></td><td>GET/POST</td><td>list (<code>?kind=</code>) / create entity</td></tr><tr><td><code>/api/entities/{id}</code></td><td>GET/DELETE</td><td>entity doc / <code>entity.delete</code></td></tr><tr><td><code>/api/entities/{id}/ops</code></td><td>POST</td><td>submit op <code>{kind, payload}</code></td></tr><tr><td><code>/api/entities/{id}/snapshot</code></td><td>GET</td><td>export snapshot bytes</td></tr><tr><td><code>/api/entities/snapshot</code></td><td>POST</td><td>import snapshot (<code>body.kind</code> picks the plane)</td></tr><tr><td><code>/api/entity-index</code></td><td>GET</td><td><code>{&quot;index&quot;: [{node, entities}]}</code> — one row, this node</td></tr><tr><td><code>/api/pending-ops</code></td><td>GET</td><td><code>{&quot;ops&quot;: [...]}</code> — always empty on a bare node (the outbox is hub-side)</td></tr><tr><td><code>/api/push/vapid</code></td><td>GET</td><td><code>{publicKey}</code> (501 without a push store)</td></tr><tr><td><code>/api/push/subscribe</code></td><td>POST/DELETE</td><td>push subscription add/remove</td></tr></tbody></table><h2 id="hub-surface" tabindex="-1">Hub surface <a class="header-anchor" href="#hub-surface" aria-label="Permalink to &quot;Hub surface&quot;">​</a></h2><p>Same <code>/api/entities*</code> shape, aggregated: merged index from all <code>HYPHA_NODES</code> nodes, ops routed to the owner (durable outbox when offline), plus hub-owned routes:</p><table tabindex="0"><thead><tr><th>Route</th><th>Purpose</th></tr></thead><tbody><tr><td><code>/api/entity-index</code></td><td>merged per-node entity buckets</td></tr><tr><td><code>/api/pending-ops</code></td><td>outbox depth — queued + dead-letter ops</td></tr><tr><td><code>/api/events</code></td><td>SSE bridge to the upstream node</td></tr><tr><td><code>/api/entities/{id}/stream</code></td><td>per-entity live stream (kind policy&#39;s <code>stream_path</code>, owning node)</td></tr><tr><td><code>/api/push/*</code></td><td>hub-owned subscription store (fans out to every node)</td></tr><tr><td><code>/api/{*rest}</code></td><td>passthrough to the upstream node for everything else</td></tr></tbody></table><p>Not on the substrate: <code>/api/config*</code> — node config is integration-owned (a composing integration mounts its own surface); <code>EntityApi::get_config</code>/<code>set_config</code> are doc-hidden for that reason.</p><h2 id="client" tabindex="-1">Client <a class="header-anchor" href="#client" aria-label="Permalink to &quot;Client&quot;">​</a></h2><p><code>hypha_node_api::HttpEntityApi</code> (ureq) implements <code>EntityApi</code>; <code>FakeEntityApi</code> is the in-memory test double. Wire DTOs: <code>EntityDto</code>, <code>EntityOp</code>, <code>EntityIndexDto</code>, <code>PendingOpDto</code>, <code>NodeInfoDto</code>, <code>NodeStatusDto</code>, <code>PushSubscriptionDto</code> — see <code>hypha-node-api/src/dto.rs</code> and the generated rustdoc under <code>/hypha/api/</code>.</p>',10)])])}const b=t(i,[["render",r]]);export{l as __pageData,b as default};
